```


**To Reproduce**
Steps to reproduce the behavior:
```java
package org.acme;

import javax.ws.rs.GET;
import javax.ws.rs.Path;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

@Path("/hello")
public class ExampleResource {

    @GET
    @Produces(MediaType.TEXT_PLAIN)
    public String hello() {
        try /* (  BufferedReader reader = new BufferedReader(new InputStreamReader(getClass().getClassLoader().getResourceAsStream("jsonpath.js")))  ) */ {
            BufferedReader reader = new BufferedReader(new InputStreamReader(getClass().getClassLoader().getResourceAsStream("jsonpath.js")));
            reader.readLine();
         }catch (IOException | NullPointerException e) {
            e.printStackTrace();
            return e.getMessage();
        }
        return "ok";
    }
}
```
```java
package org.acme;

import io.quarkus.hibernate.orm.panache.PanacheEntityBase;
import io.quarkus.runtime.annotations.RegisterForReflection;

import javax.persistence.Entity;
import javax.persistence.GeneratedValue;
import javax.persistence.GenerationType;
import javax.persistence.Id;
import javax.persistence.SequenceGenerator;
import javax.validation.constraints.NotNull;

@Entity
@RegisterForReflection
public class Example extends PanacheEntityBase {

   @Id
   @SequenceGenerator(
      name = "cellSequence",
      sequenceName = "cell_id_seq",
      allocationSize = 1,
      initialValue = 10)
   @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "cellSequence")
   public Integer id;

   @NotNull
   public String type;

   @NotNull
   public String content;

}
```
`./mvnw clean package`

